import sys
MOD=998244353

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    inf = n + 1
    exact = [[inf] * n for _ in range(n)]
    p = 2
    for _ in range(m):
        L, R, X = data[p] - 1, data[p + 1] - 1, data[p + 2] - 1
        p += 3
        if R < exact[X][L]:
            exact[X][L] = R
    threshold = [[inf] * n for _ in range(n)]
    for x in range(n):
        cur = inf
        row = threshold[x]
        for l in range(n - 1, -1, -1):
            if exact[x][l] < cur:
                cur = exact[x][l]
            row[l] = cur
    comb = [[0] * n for _ in range(n)]
    for a in range(n):
        comb[a][0] = comb[a][a] = 1
        for b in range(1, a):
            comb[a][b] = (comb[a - 1][b - 1] + comb[a - 1][b]) % MOD
    dp = [[0] * n for _ in range(n)]
    for length in range(1, n + 1):
        for l in range(n - length + 1):
            r = l + length - 1
            val = 0
            c_row = comb[length - 1]
            for k in range(l, r + 1):
                if threshold[k][l] <= r:
                    continue
                a = 1 if k == l else dp[l][k - 1]
                b = 1 if k == r else dp[k + 1][r]
                val = (val + c_row[k - l] * a * b) % MOD
            dp[l][r] = val
    print(dp[0][n - 1])

solve()

