import sys
from array import array

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    N, M = data[0], data[1]
    A = [x - 1 for x in data[2:]]

    # Remove non-cycle vertices in leaf-to-root order.
    indeg = [0] * N
    for v in range(N):
        indeg[A[v]] += 1

    queue = [v for v in range(N) if indeg[v] == 0]
    order = []
    for v in queue:
        order.append(v)
        w = A[v]
        indeg[w] -= 1
        if indeg[w] == 0:
            queue.append(w)

    # Each directed cycle becomes one component with a shared label.
    comp = [-1] * N
    node_count = 0
    for v in range(N):
        if indeg[v] > 0 and comp[v] == -1:
            cur = v
            while comp[cur] == -1:
                comp[cur] = node_count
                cur = A[cur]
            node_count += 1

    for v in range(N):
        if comp[v] == -1:
            comp[v] = node_count
            node_count += 1

    parent = [-1] * node_count
    for v in range(N):
        if indeg[v] == 0:
            parent[comp[v]] = comp[A[v]]

    # acc[u][k] accumulates the product of prefix counts contributed
    # by u's children, for each possible label k (1-indexed).
    acc = [None] * node_count
    roots = []

    for v in order:
        u = comp[v]
        dp = acc[u]
        if dp is None:
            dp = array('I', [1]) * M

        p = parent[u]
        if p == -1:
            roots.append(dp)
            continue

        target = acc[p]
        if target is None:
            target = array('I', [1]) * M
            acc[p] = target

        running = 0
        for k in range(M):
            running += dp[k]
            if running >= MOD:
                running -= MOD
            target[k] = target[k] * running % MOD

    answer = 1
    for r in range(node_count):
        if parent[r] == -1:
            dp = acc[r]
            if dp is None:
                dp = array('I', [1]) * M
            answer = answer * (sum(dp) % MOD) % MOD

    print(answer)

if __name__ == "__main__":
    main()

