import itertools, random

def fast(s):
 q=[]
 for i,c in enumerate(s):
  if c=='1':q.append(i-len(q))
 m=len(q); z=q[m//2]
 return sum(abs(x-z) for x in q)
def brute(s):
 n=len(s); k=s.count('1'); a=[i for i,c in enumerate(s) if c=='1']
 return min(sum(abs(a[j]-(x+j)) for j in range(k)) for x in range(n-k+1))
for n in range(2,13):
 for bits in itertools.product('01', repeat=n):
  s=''.join(bits)
  if '1' in s and fast(s)!=brute(s):print('bad',s,fast(s),brute(s));raise SystemExit
