import sys
MOD=998244353

def calc(p, es, B):
    pw=[1]*(B+1)
    for i in range(1,B+1):
        pw[i]=pw[i-1]*p%MOD
    dp=pw[:]
    for e in es:
        nd=[0]*(B+1)
        if e==0:
            for h,v in enumerate(dp):
                nd[h]=v*pw[h]%MOD
        else:
            for h,v in enumerate(dp):
                if v:
                    nh=h+e
                    if nh<=B:
                        nd[nh]=(nd[nh]+v*pw[nh])%MOD
                    nh=h-e
                    if nh>=0:
                        nd[nh]=(nd[nh]+v*pw[nh])%MOD
        dp=nd
    return sum(dp)%MOD

def main():
    data=list(map(int,sys.stdin.buffer.read().split()))
    n=data[0]
    a=data[1:]
    spf=list(range(1001))
    for i in range(2,32):
        if spf[i]==i:
            for j in range(i*i,1001,i):
                if spf[j]==j:
                    spf[j]=i
    edges={}
    for idx,x in enumerate(a):
        while x>1:
            p=spf[x]
            e=0
            while x%p==0:
                x//=p
                e+=1
            edges.setdefault(p,[0]*(n-1))[idx]=e
    ans=1
    for p,es in edges.items():
        H=sum(es)
        local=(calc(p,es,H)-pow(p,n,MOD)*calc(p,es,H-1))%MOD
        ans=ans*local%MOD
    print(ans)

main()

