N,M,Q=map(int,input().split())
edges=[]
for _ in range(M):
 a,b,c=map(int,input().split()); edges.append((a-1,b-1,c))
queries=[]; closed=set()
for _ in range(Q):
 t,*v=map(int,input().split()); queries.append((t,*v))
 if t==1: closed.add(v[0]-1)
INF=10**30
d=[[INF]*N for _ in range(N)]
for i in range(N): d[i][i]=0
for k,(a,b,c) in enumerate(edges):
 if k not in closed:
  d[a][b]=d[b][a]=c
for k in range(N):
 dk=d[k]
 for i in range(N):
  dik=d[i][k]
  if dik==INF: continue
  di=d[i]
  for j in range(N):
   x=dik+dk[j]
   if x<di[j]: di[j]=x
