import sys
import math

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, budget = data[0], data[1]
    machines = []
    idx = 2
    for _ in range(n):
        a, p, b, q = data[idx:idx + 4]
        idx += 4
        period = b // math.gcd(a, b)
        machines.append((a, p, b, q, period))

    def feasible(target):
        total = 0
        for a, p, b, q, period in machines:
            # Buying only S machines is always one candidate.
            best = ((target + a - 1) // a) * p
            max_x = (target - 1) // a

            # For each residue of x modulo period, the cost is linear as
            # x advances by period while the remaining requirement is positive.
            for r in range(min(period, max_x + 1)):
                last = r + ((max_x - r) // period) * period
                for x in (r, last):
                    y = (target - a * x + b - 1) // b
                    cost = x * p + y * q
                    if cost < best:
                        best = cost

            total += best
            if total > budget:
                return False
        return True

    low, high = 0, budget * 100 + 1
    while low + 1 < high:
        mid = (low + high) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid
    print(low)

if __name__ == '__main__':
    main()

