class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        L = len(s)

        # C[i][j] = number of ways to choose j set bits among i positions.
        C = [[0] * (L + 1) for _ in range(L + 1)]
        for i in range(L + 1):
            C[i][0] = C[i][i] = 1
            for j in range(1, i):
                C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % MOD

        # A positive integer with t set bits needs 1 + steps(t) operations.
        good = [False] * (L + 1)
        for t in range(1, L + 1):
            x = t
            steps = 0
            while x > 1:
                x = x.bit_count()
                steps += 1
            good[t] = steps + 1 <= k

        # Count numbers strictly below s by considering the first differing bit.
        ans = 0
        ones_so_far = 0
        for i, bit in enumerate(s):
            if bit == '1':
                remaining = L - i - 1
                for total_ones in range(1, L + 1):
                    needed = total_ones - ones_so_far
                    if 0 <= needed <= remaining and good[total_ones]:
                        ans += C[remaining][needed]
                ones_so_far += 1

        return ans % MOD

