        p += 2
        rows[u] |= 1 << v
        rows[v] |= 1 << u

    rank = 0
    pivots = []
    for c in range(n):
        r = next((i for i in range(rank, n) if (rows[i] >> c) & 1), None)
        if r is None:
            continue
        rows[rank], rows[r] = rows[r], rows[rank]
        for i in range(n):
            if i != rank and ((rows[i] >> c) & 1):
                rows[i] ^= rows[rank]
        pivots.append(c)
        rank += 1

    pivot_set = set(pivots)
    basis = []
    for f in range(n):
        if f in pivot_set:
            continue
        x = 1 << f
        for i, c in enumerate(pivots):
            if (rows[i] >> f) & 1:
                x |= 1 << c
        basis.append(x)

    vals = [0] * n
    shift = 2 if m > 0 and len(basis) <= 58 else 0
    for k, x in enumerate(basis):
        for v in range(n):
            if (x >> v) & 1:
                vals[v] |= 1 << (k + shift)

