        r = next((i for i in range(rank, n) if (rows[i] >> c) & 1), None)
        if r is None:
            continue
        rows[rank], rows[r] = rows[r], rows[rank]
        for i in range(n):
            if i != rank and ((rows[i] >> c) & 1):
                rows[i] ^= rows[rank]
        pivots.append(c)
        rank += 1

    pivot_set = set(pivots)
    basis = []
    for f in range(n):
