import sys
import math

N = int(sys.stdin.buffer.readline())
answer = None

# Since N = (x-y)(x^2+xy+y^2) >= (x-y)^3,
# the difference d=x-y is at most floor(cuberoot(N)) <= 10^6.
for d in range(1, 1_000_001):
    if d * d * d > N:
        break
    if N % d != 0:
        continue

    # N/d = 3*y^2 + 3*d*y + d^2
    discriminant = 12 * (N // d) - 3 * d * d
    if discriminant < 0:
        continue
    root = math.isqrt(discriminant)
    if root * root != discriminant:
        continue

    numerator = root - 3 * d
    if numerator <= 0 or numerator % 6 != 0:
        continue

    y = numerator // 6
    x = y + d
    if x * x * x - y * y * y == N:
        answer = (x, y)
        break

if answer is None:
    print(-1)
else:
    print(*answer)

