class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        dirs = [(-1, 1), (1, 1), (1, -1), (-1, -1)]  # clockwise
        # straight[r][c][d]: valid alternating sequence length including this cell
        straight = [[[0] * 4 for _ in range(m)] for _ in range(n)]
        for d, (dr, dc) in enumerate(dirs):
            rows = range(n - 1, -1, -1) if dr > 0 else range(n)
            cols = range(m - 1, -1, -1) if dc > 0 else range(m)
            for r in rows:
                for c in cols:
                    best = 1
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < n and 0 <= nc < m:
                        v = grid[r][c]
                        want = 2 if v in (0, 1) else 0
                        if grid[nr][nc] == want:
                            best += straight[nr][nc][d]
                    straight[r][c][d] = best

        # f: best path from this cell in direction d, with its one turn still available.
        f = [[[0] * 4 for _ in range(m)] for _ in range(n)]
        ans = 0
        for d, (dr, dc) in enumerate(dirs):
            td = (d + 1) % 4
            rows = range(n - 1, -1, -1) if dr > 0 else range(n)
            cols = range(m - 1, -1, -1) if dc > 0 else range(m)
            tr, tc = dirs[td]
            for r in rows:
                for c in cols:
                    val = 1
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < n and 0 <= nc < m:
                        want = 2 if grid[r][c] in (0, 1) else 0
                        if grid[nr][nc] == want:
                            val = max(val, 1 + f[nr][nc][d])
                            # Turn at the current cell; next cell follows clockwise direction.
                            ar, ac = r + tr, c + tc
                            if 0 <= ar < n and 0 <= ac < m and grid[ar][ac] == want:
                                val = max(val, 1 + straight[ar][ac][td])
                    f[r][c][d] = val
                    if grid[r][c] == 1:
                        ans = max(ans, val)
        return ans

