from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i

        used = [False] * (n + 1)
        odd_left = (n + 1) // 2
        even_left = n // 2
        previous_parity = None
        result = []

        for pos in range(n):
            chosen = False
            for x in range(1, n + 1):
                if used[x]:
                    continue
                parity = x % 2
                if previous_parity is not None and parity == previous_parity:
                    continue

                remaining_odds = odd_left - (parity == 1)
                remaining_evens = even_left - (parity == 0)
                remaining_positions = n - pos - 1

                if remaining_positions == 0:
                    ways = 1
                else:
                    # The next element must have parity opposite to x.
                    odd_slots = ((remaining_positions + 1) // 2
                                 if parity == 0 else remaining_positions // 2)
                    even_slots = remaining_positions - odd_slots
                    if remaining_odds == odd_slots and remaining_evens == even_slots:
                        ways = fact[remaining_odds] * fact[remaining_evens]
                    else:
                        ways = 0

                if k > ways:
                    k -= ways
                elif ways > 0:
                    result.append(x)
                    used[x] = True
                    odd_left = remaining_odds
                    even_left = remaining_evens
                    previous_parity = parity
                    chosen = True
                    break

            if not chosen:
                return []

        return result

