class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2
        powers = [1] * n
        for i in range(1, n):
            powers[i] = powers[i - 1] * 10 % k

        weights = [0] * m
        for i in range(m):
            j = n - 1 - i
            weights[i] = (powers[i] + (powers[j] if j != i else 0)) % k

        # suffix[i] is a bitmask of residues achievable using positions i..m-1.
        suffix = [0] * (m + 1)
        suffix[m] = 1  # residue zero
        for i in range(m - 1, -1, -1):
            mask = suffix[i + 1]
            w = weights[i]
            reachable = 0
            for digit in range(10):
                for residue in range(k):
                    if mask >> residue & 1:
                        reachable |= 1 << ((residue + digit * w) % k)
            suffix[i] = reachable

        # Greedily choose the largest digit that leaves a feasible suffix.
        digits = []
        remainder = 0
        for i, w in enumerate(weights):
            lowest = 1 if i == 0 else 0
            for digit in range(9, lowest - 1, -1):
                needed = (-remainder - digit * w) % k
                if suffix[i + 1] >> needed & 1:
                    digits.append(str(digit))
                    remainder = (remainder + digit * w) % k
                    break

        half = ''.join(digits)
        return half + (half[:-1] if n % 2 else half)[::-1]

