from typing import List

class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        # next strictly greater element
        nxt = [n] * n
        st = []
        for i, x in enumerate(nums):
            while st and nums[st[-1]] < x:
                nxt[st.pop()] = i
            st.append(i)

        levels = n.bit_length()
        jump = [nxt]
        total = [[nums[i] * (nxt[i] - i) for i in range(n)]]
        for p in range(1, levels):
            prevj = jump[-1]
            preva = total[-1]
            jj = [n] * n
            aa = [0] * n
            for i in range(n):
                mid = prevj[i]
                if mid < n:
                    jj[i] = prevj[mid]
                    aa[i] = preva[i] + preva[mid]
                else:
                    aa[i] = preva[i]
            jump.append(jj)
            total.append(aa)

        pref = [0] * (n + 1)
        for i, x in enumerate(nums):
            pref[i + 1] = pref[i] + x

        def cost(l: int, r: int) -> int:
            pos = l
            s = 0
            for p in range(levels - 1, -1, -1):
                q = jump[p][pos]
                if q <= r:
                    s += total[p][pos]
                    pos = q
            s += nums[pos] * (r - pos + 1)
            return s - (pref[r + 1] - pref[l])

        ans = 0
        for l in range(n):
            lo, hi = l, n - 1
            while lo < hi:
                mid = (lo + hi + 1) // 2
                if cost(l, mid) <= k:
                    lo = mid
                else:
                    hi = mid - 1
            ans += lo - l + 1
        return ans

