from typing import List

class Solution:
    def maximumSubarrayXor(self, nums: List[int], queries: List[List[int]]) -> List[int]:
        n = len(nums)
        dp = [None] * n

        # First compute the XOR score for every interval.
        for i in range(n - 1, -1, -1):
            row = [0] * (n - i)
            row[0] = nums[i]
            if i + 1 < n:
                next_row = dp[i + 1]
                for length_offset in range(1, n - i):
                    row[length_offset] = row[length_offset - 1] ^ next_row[length_offset - 1]
            dp[i] = row

        # Convert each score into the maximum score over subintervals.
        for i in range(n - 1, -1, -1):
            row = dp[i]
            if i + 1 < n:
                next_row = dp[i + 1]
                for offset in range(1, n - i):
                    row[offset] = max(row[offset], row[offset - 1], next_row[offset - 1])

        return [dp[left][right - left] for left, right in queries]

