                    row[length_offset] = row[length_offset - 1] ^ next_row[length_offset - 1]
            dp[i] = row

        # Convert each score into the maximum score over subintervals.
        for i in range(n - 1, -1, -1):
            row = dp[i]
            if i + 1 < n:
                next_row = dp[i + 1]
                for offset in range(1, n - i):
                    row[offset] = max(row[offset], row[offset - 1], next_row[offset - 1])

        return [dp[left][right - left] for left, right in queries]

