# implement algorithm equivalent quickly and brute
for n in range(2,10):
 for _ in range(50):
  edges=[(v,random.randrange(v),random.randint(1,9)) for v in range(1,n)]
  par=[-1]*n; pw=[0]*n; adj=[[]for i in range(n)]
  for a,b,w in edges:adj[a].append((b,w));adj[b].append((a,w))
  order=[0]
  for x in order:
   for y,w in adj[x]:
    if y!=par[x]:par[y]=x;pw[y]=w;order.append(y)
  ans=[0]*n
  for mask in range(1,1<<n):
   cov=0
   for v in range(1,n):
    x=v
    while x and not(mask>>x&1):x=par[x]
    if x: continue
    # edge parent[v]-v covered iff selected in subtree v
    stack=[v];found=False
    while stack:
     z=stack.pop()
     if mask>>z&1:found=True;break
     stack.extend(y for y,w in adj[z] if par[y]==z)
    if found:cov+=pw[v]
   ans[mask.bit_count()-1]=max(ans[mask.bit_count()-1],2*cov)
